const body = $input.first().json.body;
const year = new Date().getFullYear();

const POSTGREST = $('Config').first().json.POSTGREST_URL;
const JWT = $('Config').first().json.POSTGREST_JWT;

// Use DB sequence via next_po_number-style RPC to avoid random collisions
// Falls back to timestamp-based suffix if RPC unavailable
let seq;
try {
  const seqRes = await this.helpers.httpRequest({
    method: 'POST',
    url: POSTGREST + '/rpc/next_ticket_reference',
    headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json' },
    body: JSON.stringify({ p_year: year })
  });
  seq = String(seqRes).padStart(4, '0');
} catch (e) {
  // Fallback: millisecond-precision timestamp suffix (collision-safe for demo volumes)
  seq = String(Date.now()).slice(-6);
}
const reference = 'TS-' + year + '-' + seq;

const payload = {
  reference,
  source: 'intake',
  status: 'reasoning',
  title: body.title || body.description || 'Untitled',
  description: body.description || '',
  ticket_type: body.ticket_type || 'purchase',
  submitted_by: body.submitted_by || '',
  submitted_by_email: body.submitted_by_email || '',
  supplier_name: body.supplier_name || '',
  value_eur: parseFloat(body.value_eur || body.amount || 0),
  category: body.category || 'other',
  branch_id: body.branch_id || null
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/tickets',
  headers: {
    'Authorization': 'Bearer ' + JWT,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify(payload),
  returnFullResponse: true
});

const ticket = response.body[0] || response.body;

return [{ json: { ticket, reference, body } }];

const intake = $node['Intake Form Submitted'].json.body;
const supplier = $node['Fetch Supplier Context'].json;
const budget = $node['Fetch Budget Context'].json;
const manager = $node['Fetch Responsible Manager'].json;

const JWT = $('Config').first().json.POSTGREST_JWT;
const POSTGREST = $('Config').first().json.POSTGREST_URL;

const amount = parseFloat(intake.value_eur || intake.amount || 0);
const costCenterId = intake.cost_center_id || null;
const branchId = intake.branch_id || null;
const period = new Date().getFullYear() + '-Q' + Math.ceil((new Date().getMonth()+1)/3);
const category = intake.category || 'other';

// Fetch CC-level budget position if cost_center_id provided
let budgetCC = null;
if (costCenterId && branchId) {
  try {
    const ccBudget = await this.helpers.httpRequest({
      method: 'GET',
      url: POSTGREST + '/budget_positions?branch_id=eq.' + branchId + '&cost_center_id=eq.' + costCenterId + '&period=eq.' + period,
      headers: { 'Authorization': 'Bearer ' + JWT, 'Accept': 'application/json' }
    });
    budgetCC = ccBudget[0] || null;
  } catch(e) { budgetCC = null; }
}

// Spend authority check
const managerAuthority = parseFloat(manager[0]?.spend_authority || 0);
let forceDisposition = null;
let blockReason = null;

if (amount > 100000) {
  forceDisposition = 'escalate';
} else if (managerAuthority > 0 && amount > managerAuthority) {
  forceDisposition = 'one_touch';
}

// CC budget check: block if no budget position exists for this CC+category
let budgetWarning = null;
if (costCenterId && !budgetCC) {
  budgetWarning = 'No budget position found for cost centre + category ' + category + ' in ' + period + '. Request requires budget allocation before approval.';
  if (!forceDisposition) forceDisposition = 'one_touch'; // flag for review
} else if (budgetCC) {
  const remaining = (budgetCC.budget - budgetCC.committed - budgetCC.spent);
  if (amount > remaining) {
    budgetWarning = 'Request amount EUR ' + amount + ' exceeds remaining CC budget of EUR ' + remaining + ' (budget: ' + budgetCC.budget + ', committed: ' + budgetCC.committed + ', spent: ' + budgetCC.spent + ')';
    if (!forceDisposition) forceDisposition = 'one_touch';
  }
}

// New supplier check
const supplierFound = Array.isArray(supplier) && supplier.length > 0;
const supplierApproved = supplierFound && supplier[0].compliance_status === 'green';
const needsCompliance = !supplierApproved;

return [{ json: {
  forceDisposition,
  budgetCC,
  budgetWarning,
  needsCompliance,
  supplierFound,
  supplierApproved,
  managerAuthority,
  amount
} }];

const intake = $node['Intake Form Submitted'].json.body;
const supplier = $node['Fetch Supplier Context'].json;
const contract = $node['Fetch Contract Context'].json;
const budget = $node['Fetch Budget Context'].json;
const manager = $node['Fetch Responsible Manager'].json;
const preCheck = $node['Pre-Check Gate'].json;

const ANTHROPIC_KEY = $('Config').first().json.ANTHROPIC_API_KEY;

const forceNote = preCheck.forceDisposition
  ? `\nFORCED DISPOSITION: The system has pre-determined this must be "${preCheck.forceDisposition}". Reason: ${preCheck.budgetWarning || (preCheck.forceDisposition === 'escalate' ? 'Amount exceeds â‚¬100,000' : 'Amount exceeds manager spend authority')}. You MUST return this disposition.`
  : '';

const ccBudgetNote = preCheck.budgetCC
  ? `\nCC BUDGET: ${JSON.stringify(preCheck.budgetCC)} â€” remaining: EUR ${preCheck.budgetCC.budget - preCheck.budgetCC.committed - preCheck.budgetCC.spent}`
  : (preCheck.budgetWarning ? `\nCC BUDGET WARNING: ${preCheck.budgetWarning}` : '');

const complianceNote = preCheck.needsCompliance
  ? '\nCOMPLIANCE FLAG: Supplier is new or not yet compliance-approved. If disposition is auto_execute, downgrade to one_touch. A compliance review is required before PO issuance.'
  : '';

const prompt = `Reason on this procurement intake request and return a disposition.

REQUEST:
${JSON.stringify(intake)}

SIGNAL 1 - CONTRACT:
${JSON.stringify(contract)}

SIGNAL 2 - BUDGET:
${JSON.stringify(budget)}

SIGNAL 3 - SUPPLIER:
${JSON.stringify(supplier)}

SIGNAL 4 - REQUEST: ${intake.ticket_type || 'purchase'} for EUR ${intake.value_eur || intake.amount || 0} by ${intake.submitted_by || 'unknown'}

SIGNAL 5 - POLICY:
- CATALOG ITEMS (description contains SKU codes like APPMBP14M3PRO, GHENT, MS365E3 etc): These are pre-approved catalog items with contracts already on file. If budget is available, ALWAYS return auto_execute with confidence >= 0.95. Do not route catalog items to one_touch under any circumstance unless the budget bucket is completely exhausted.
- Auto-execute if all 5 signals green and confidence >= 0.85.
- One-touch if any signal uncertain or confidence < 0.85.
- Escalate if amount > EUR 100000 OR compliance blocker detected.${forceNote}${ccBudgetNote}${complianceNote}

Return ONLY valid JSON (no markdown, no explanation outside JSON):
{
  "disposition": "auto_execute" or "one_touch" or "escalate",
  "confidence": 0.0 to 1.0,
  "reasoning": "string â€” explain each of the 5 signals",
  "recommendation": "string â€” one sentence action",
  "brief": "string â€” one sentence for the submitter",
  "action_taken": "string",
  "supplier_email_subject": "string or null",
  "supplier_email_body": "string or null",
  "requires_order": true or false,
  "signals": [
    { "signal": "contract",    "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "policy",      "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "supplier",    "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "request",     "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." },
    { "signal": "consumption", "value": "...", "weight": 0.0-1.0, "green": true/false, "notes": "..." }
  ]
}`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': ANTHROPIC_KEY,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 1500,
    messages: [{ role: 'user', content: prompt }]
  })
});

const text = response.content[0].text;
// Strip markdown fences if Claude wraps in them
const clean = text.replace(/^```json\n?/,'').replace(/\n?```$/,'').trim();
const result = JSON.parse(clean);

// Enforce force_disposition from pre-check gate â€” override Claude if it deviated
if (preCheck.forceDisposition && result.disposition !== preCheck.forceDisposition) {
  result.disposition = preCheck.forceDisposition;
}

return [{ json: result }];

const result = $input.first().json;
const ticketId = $node['Create Ticket in PostgREST'].json.ticket?.id;
const JWT = $('Config').first().json.POSTGREST_JWT;
const POSTGREST = $('Config').first().json.POSTGREST_URL;

const decisionId = await this.helpers.httpRequest({
  method: 'POST',
  url: POSTGREST + '/rpc/record_decision',
  headers: { 'Authorization': 'Bearer ' + JWT, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    p_ticket_id: ticketId,
    p_disposition: result.disposition,
    p_confidence: result.confidence,
    p_reasoning: result.reasoning,
    p_recommendation: result.recommendation,
    p_brief: result.brief,
    p_model_used: 'claude-sonnet-4-6'
  })
});

return [{ json: { ...result, decision_id: decisionId, ticket_id: ticketId } }];

const intake = $node['Intake Form Submitted'].json.body;
const result = $node['Write Decision to PostgREST'].json;
